/**
 * Render a Lucide icon inline. Inherits currentColor.
 *
 * @param string $name  Icon name.
 * @param int    $size  Pixel size (width & height).
 * @param array  $args  Optional: 'class', 'stroke' (width), 'label' (aria-label).
 */
function sdi_icon( $name, $size = 24, $args = array() ) {
	static $paths = null;
	if ( null === $paths ) {
		$paths = sdi_icon_paths();
	}
	if ( empty( $paths[ $name ] ) ) {
		return '';
	}
	$size   = (int) $size;
	$class  = 'sdi-icon' . ( isset( $args['class'] ) ? ' ' . $args['class'] : '' );
	$stroke = isset( $args['stroke'] ) ? (float) $args['stroke'] : 2;
	$aria   = isset( $args['label'] ) ? ' role="img" aria-label="' . esc_attr( $args['label'] ) . '"' : ' aria-hidden="true"';

	return sprintf(
		'<svg class="%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="%3$s" stroke-linecap="round" stroke-linejoin="round"%4$s>%5$s</svg>',
		esc_attr( $class ),
		$size,
		esc_attr( $stroke ),
		$aria,
		$paths[ $name ] // phpcs:ignore WordPress.Security.EscapeOutput -- trusted static SVG markup.
	);
}

/** Echo helper. */
function sdi_the_icon( $name, $size = 24, $args = array() ) {
	echo sdi_icon( $name, $size, $args ); // phpcs:ignore WordPress.Security.EscapeOutput -- sdi_icon returns safe SVG.
}
